// A3's terminal apps (TERMINALS in sidecar/hardlimits-core.mjs): their text area's last line goes to the sidecar, whose
// passwordPrompt refuses typing at a sudo or ssh prompt. Written by node test/swiftsync.mjs --write.
let TERMINALS = try! NSRegularExpression(pattern: #"^(terminal|iterm2?|warp|ghostty|kitty|alacritty|wezterm|hyper|tabby|rio|wave)$"#, options: [.caseInsensitive])

enum Hit {
    typealias LabelledElement = (label: String, element: AXUIElement)

    struct Control {
        let element: AXUIElement
        let role: String
        let label: String
        let rect: [Double]
        let subrole: String?
        let enabled: Bool?

        init?(_ element: AXUIElement) {
            guard let role = Hit.str(element, kAXRoleAttribute), let rect = Hit.rect(element),
                  rect.allSatisfy(\.isFinite), rect[2] > 0, rect[3] > 0 else { return nil }
            self.element = element
            self.role = role
            self.label = Hit.label(element)
            self.rect = rect
            self.subrole = Hit.str(element, kAXSubroleAttribute)
            self.enabled = Hit.attr(element, kAXEnabledAttribute) as? Bool
        }

        func matches(_ other: Control) -> Bool {
            CFEqual(element, other.element) && role == other.role && label == other.label && rect == other.rect &&
            subrole == other.subrole && enabled == other.enabled
        }
    }

    struct Target {
        let pid: pid_t
        let launched: Date
        let screen: CGDirectDisplayID
        let bounds: CGRect
        let control: Control
        let window: Control
        let document: String?
        let related: [LabelledElement]

        init?(_ element: AXUIElement, window: AXUIElement, related: [LabelledElement], screen: CGDirectDisplayID, point: CGPoint?) {
            var pid: pid_t = 0, windowPid: pid_t = 0
            guard AXUIElementGetPid(element, &pid) == .success, pid > 0,
                  AXUIElementGetPid(window, &windowPid) == .success, pid == windowPid,
                  let app = NSRunningApplication(processIdentifier: pid), let launched = app.launchDate,
                  !app.isTerminated, CGDisplayIsActive(screen) != 0,
                  let control = Control(element), let window = Control(window) else { return nil }
            let bounds = CGDisplayBounds(screen)
            let r = control.rect
            let frame = CGRect(x: r[0], y: r[1], width: r[2], height: r[3])
            guard bounds.intersects(frame) else { return nil }
            if let point {
                guard bounds.contains(point), frame.contains(point),
                      !["AXWindow", "AXApplication", "AXWebArea", "AXUnknown"].contains(control.role) else { return nil }
            }
            self.pid = pid
            self.launched = launched
            self.screen = screen
            self.bounds = bounds
            self.control = control
            self.window = window
            self.document = Hit.attr(window.element, kAXDocumentAttribute) as? String
            self.related = related
        }

        func matches(_ other: Target) -> Bool {
            pid == other.pid && launched == other.launched && screen == other.screen && bounds == other.bounds &&
            control.matches(other.control) && window.matches(other.window) && document == other.document &&
            related.count == other.related.count && zip(related, other.related).allSatisfy { a, b in
                a.label == b.label && CFEqual(a.element, b.element)
            }
        }
    }

    static func attr(_ e: AXUIElement, _ name: String) -> CFTypeRef? {
        var v: CFTypeRef?
        return AXUIElementCopyAttributeValue(e, name as CFString, &v) == .success ? v : nil
    }
    static func canPress(_ element: AXUIElement) -> Bool {
        var actions: CFArray?
        return AXUIElementCopyActionNames(element, &actions) == .success &&
            ((actions as? [String])?.contains(kAXPressAction as String) == true)
    }
    static func str(_ e: AXUIElement, _ name: String) -> String? { (attr(e, name) as? String).flatMap { $0.isEmpty ? nil : String($0.prefix(120)) } }
    static func label(_ e: AXUIElement) -> String {
        for n in [kAXTitleAttribute, kAXDescriptionAttribute, "AXPlaceholderValue", kAXHelpAttribute] { if let s = str(e, n as String) { return s } }
        // Static text is named by its text (a web page's "Buy" in a clickable div): text on screen, never a field's value.
        if str(e, kAXRoleAttribute) == "AXStaticText", let v = str(e, kAXValueAttribute) { return v }
        // A button's title can sit on its static-text child.
        if let kids = attr(e, kAXChildrenAttribute) as? [AXUIElement], kids.count == 1, str(kids[0], kAXRoleAttribute) == "AXStaticText" { return str(kids[0], kAXValueAttribute) ?? "" }
        return ""
    }
    static func rect(_ e: AXUIElement) -> [Double]? {
        guard let pv = attr(e, kAXPositionAttribute), let sv = attr(e, kAXSizeAttribute) else { return nil }
        var p = CGPoint.zero, s = CGSize.zero
        guard AXValueGetValue(pv as! AXValue, .cgPoint, &p), AXValueGetValue(sv as! AXValue, .cgSize, &s) else { return nil }
        return [p.x, p.y, s.width, s.height].map { Double($0) }
    }
    static func secure(_ e: AXUIElement) -> Bool { str(e, kAXSubroleAttribute) == "AXSecureTextField" || str(e, kAXRoleAttribute) == "AXSecureTextField" }
    static func appName(_ e: AXUIElement) -> String {
        var pid: pid_t = 0
        AXUIElementGetPid(e, &pid)
        return NSRunningApplication(processIdentifier: pid)?.localizedName ?? ""
    }

    /// A Paste menu item in any language: its shortcut is cmd+V (AXMenuItemCmdModifiers 0 is cmd alone; bit 3 means
    /// no cmd; shift and option add bits and still paste: Paste and Match Style).
    static func paste(_ e: AXUIElement) -> Bool {
        guard let c = str(e, "AXMenuItemCmdChar"), c.uppercased() == "V" else { return false }
        let mods = (attr(e, "AXMenuItemCmdModifiers") as? Int) ?? 0
        return mods & 8 == 0
    }
    /// A field named for a password, a code, a key or a card (its expiry too): A3's credentialLabel with cardForm, as
    /// remotepolicy.mjs reads it, on the label folded the same way (CRED_FIELD_CARD at the top, generated).
    static func credential(_ label: String) -> Bool {
        let raw = label.precomposedStringWithCompatibilityMapping.lowercased().replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression).trimmingCharacters(in: .whitespacesAndNewlines)
        if raw.isEmpty { return false }
        let folded = raw.folding(options: [.diacriticInsensitive, .widthInsensitive], locale: nil)
        return [raw, folded].contains { CRED_FIELD_CARD.firstMatch(in: $0, range: NSRange($0.startIndex..., in: $0)) != nil }
    }
    /// Kept in sync with PASTE in remotepolicy.mjs.
    static let pasteRx = try! NSRegularExpression(pattern: "^(paste|einsetzen|einfügen|coller|pegar|colar|incolla|plakken|wklej|вставить|vložit|beillesztés|yapıştır|klistra in|lim inn|sæt ind|indsæt|liitä|επικόλληση|הדבק|لصق|chèn|tempel|วาง|粘贴|貼上|ペースト|貼り付け|붙여넣기)(\\s|$|…)", options: [.caseInsensitive])
    static func pasteLabel(_ l: String) -> Bool { let t = l.trimmingCharacters(in: .whitespaces); return pasteRx.firstMatch(in: t, range: NSRange(t.startIndex..., in: t)) != nil }
    /// Kept in sync with PM_FILL and PM_NAME in remotepolicy.mjs: a password manager's fill item, refused on every
    /// click: a fill phrase anywhere, a manager's bare name only on a menu or a toolbar (pmMenu).
    static let pmFillRx = try! NSRegularExpression(pattern: "auto-?fill|\\bfill (in )?(the )?(login|logins|username|password|passwords|credentials?|identity|card)\\b|use (a |this |strong |suggested )?(password|passkey)|suggested password|passwords…|passwords\\.\\.\\.|^passwords$|select a password", options: [.caseInsensitive])
    static let pmNameRx = try! NSRegularExpression(pattern: "\\b(keychain|1password|bitwarden|lastpass|dashlane|keeper|proton pass|nordpass|enpass|roboform)\\b", options: [.caseInsensitive])
    static let pmMenu: Set<String> = ["AXMenuItem", "AXMenu", "AXMenuBar", "AXMenuBarItem", "AXMenuButton", "AXPopUpButton", "AXToolbar"]
    static func match(_ rx: NSRegularExpression, _ l: String) -> Bool { let t = l.trimmingCharacters(in: .whitespaces); return rx.firstMatch(in: t, range: NSRange(t.startIndex..., in: t)) != nil }
    static func pmFill(labels: [String], roles: [String]) -> Bool {
        labels.contains { match(pmFillRx, $0) } || (roles.contains(where: pmMenu.contains) && labels.contains { match(pmNameRx, $0) })
    }
    /// The on-screen keyboards that type wherever focus is (KEYBOARDS in remotepolicy.mjs).
    static func keyboard(_ app: String) -> Bool { ["assistivecontrol", "accessibility keyboard", "keyboard viewer", "characterpalette", "character viewer", "emoji & symbols", "textinputmenuagent"].contains { app.lowercased().contains($0) } }

    /// p: global points, top-left.
    static func at(_ p: CGPoint, target: ((AXUIElement, AXUIElement, [LabelledElement]) -> Void)? = nil) -> [String: Any] {
        var el: AXUIElement?
        guard AXUIElementCopyElementAtPosition(AXUIElementCreateSystemWide(), Float(p.x), Float(p.y), &el) == .success, let e = el else { return ["role": ""] }
        var labels: [String] = [], roles: [String] = [], cur: AXUIElement? = e
        var labelledParents: [LabelledElement] = []
        var pastes = false
        for i in 0 ..< 4 {
            guard let c = cur else { break }
            let title = label(c)
            if target != nil && i > 0 && !title.isEmpty { labelledParents.append((title, c)) }
            labels.append(title); roles.append(str(c, kAXRoleAttribute) ?? ""); pastes = pastes || paste(c)
            cur = attr(c, kAXParentAttribute).map { $0 as! AXUIElement }
        }
        if let target, let w = containingWindow(e) { target(e, w, labelledParents) }
        return ["role": roles[0], "label": labels[0], "labels": labels, "roles": roles, "secure": secure(e), "paste": pastes, "app": appName(e)]
    }

    static func containingWindow(_ element: AXUIElement) -> AXUIElement? {
        if let w = attr(element, kAXWindowAttribute), CFGetTypeID(w) == AXUIElementGetTypeID() { return (w as! AXUIElement) }
        var parent: AXUIElement? = element
        for _ in 0 ..< 40 {
            guard let e = parent else { break }
            if str(e, kAXRoleAttribute) == "AXWindow" { return e }
            parent = attr(e, kAXParentAttribute).map { $0 as! AXUIElement }
        }
        return nil
    }

    /// The button labels in a window (a web page's whole form included), breadth first. ponytail: 600 elements and
    /// 60 labels at most; a pay button deeper than that is not seen (read only for Return, Space and a newline).
    static func buttons(in w: AXUIElement) -> [LabelledElement] {
        var queue = [w], out: [LabelledElement] = [], seen = 0
        while !queue.isEmpty && seen < 600 && out.count < 60 {
            let e = queue.removeFirst(); seen += 1
            if str(e, kAXRoleAttribute) == "AXButton" { let l = label(e); if !l.isEmpty { out.append((l, e)) } }
            if let kids = attr(e, kAXChildrenAttribute) as? [AXUIElement] { queue.append(contentsOf: kids) }
        }
        return out
    }

    static func focus(buttons: Bool = false, target: ((AXUIElement, AXUIElement, [LabelledElement]) -> Void)? = nil,
                      observe: ((AXUIElement?) -> Void)? = nil) -> [String: Any] {
        let sys = AXUIElementCreateSystemWide()
        var out: [String: Any] = ["secureInput": IsSecureEventInputEnabled()]
        let focused = attr(sys, kAXFocusedUIElementAttribute).map { $0 as! AXUIElement }
        observe?(focused)
        if let e = focused {
            out["role"] = str(e, kAXRoleAttribute) ?? ""
            out["label"] = label(e)
            out["secure"] = secure(e)
            if let r = rect(e) { out["rect"] = r }
            // Whose element has key focus: a password manager's panel can hold it while another app is front.
            var pid: pid_t = 0
            if AXUIElementGetPid(e, &pid) == .success, pid > 0 { out["pid"] = Int(pid); out["app"] = appName(e) }
            // A terminal's last line (a sudo, ssh or gpg prompt shows no field): the sidecar's passwordPrompt reads it.
            if let app = out["app"] as? String, out["role"] as? String == "AXTextArea", TERMINALS.firstMatch(in: app, range: NSRange(location: 0, length: (app as NSString).length)) != nil, let l = lastLine(e) { out["lastLine"] = l }
        }
        if let a = attr(sys, kAXFocusedApplicationAttribute), let w = attr(a as! AXUIElement, kAXFocusedWindowAttribute) {
            let window = w as! AXUIElement
            let button: LabelledElement? = attr(window, kAXDefaultButtonAttribute).map { raw in
                let element = raw as! AXUIElement
                return (label(element), element)
            }
            if let button { out["defaultButton"] = button.label }
            let controls = buttons ? Self.buttons(in: window) : []
            if buttons { out["buttons"] = controls.map(\.label) }
            if let target, let focused, let parent = containingWindow(focused), CFEqual(parent, window) {
                target(focused, window, (button.map { [$0] } ?? []) + controls)
            }
        }
        return out
    }

    /// The last line with text of a text area, from its last 400 characters only (a terminal's scrollback is long).
    /// ponytail: GUESS (not read on a real Mac): Terminal and iTerm2 answer kAXStringForRange on their text area; a
    /// terminal that does not sends no lastLine, and its prompt is judged by macOS secure input alone.
    static func lastLine(_ e: AXUIElement) -> String? {
        var n: CFTypeRef?
        guard AXUIElementCopyAttributeValue(e, kAXNumberOfCharactersAttribute as CFString, &n) == .success, let count = n as? Int, count > 0 else { return nil }
        var r = CFRange(location: max(0, count - 400), length: min(400, count))
        guard let rv = AXValueCreate(.cfRange, &r) else { return nil }
        var s: CFTypeRef?
        guard AXUIElementCopyParameterizedAttributeValue(e, kAXStringForRangeParameterizedAttribute as CFString, rv, &s) == .success, let text = s as? String else { return nil }
        return text.components(separatedBy: .newlines).map { $0.trimmingCharacters(in: .whitespaces) }.last(where: { !$0.isEmpty }).map { String($0.prefix(160)) } ?? ""
    }

    /// A password manager's Copy (1Password, Passwords, Bitwarden) marks the clipboard concealed or transient
    /// (nspasteboard.org): a paste from the phone would draw the password on screen, in the stream. Types only, never
    /// the clipboard's contents.
    static let concealedTypes: Set<String> = ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType"]
    static func concealed(_ types: [String]) -> Bool { types.contains(where: concealedTypes.contains) }
    static func clipboardSecret() -> Bool { concealed(NSPasteboard.general.types?.map(\.rawValue) ?? []) }

    /// Key focus in an app whose window the capture leaves out (a password app: the sidecar's `exclude`). pids: window
    /// id to owner pid, from the last window list.
    static func focusExcluded(_ pid: Int?, exclude: Set<Int>, pids: [Int: Int]) -> Bool {
        guard let pid else { return false }
        return exclude.contains { pids[$0] == pid }
    }

    static func locked() -> Bool {
        guard let d = CGSessionCopyCurrentDictionary() as? [String: Any] else { return false }
        return (d["CGSSessionScreenIsLocked"] as? Bool) == true || (d["CGSSessionScreenIsLocked"] as? Int) == 1
    }
}
